fn solve(t: Vec<char>) -> Vec<char> {
    // Pre-allocate the output vector with the same length as the input
    let mut out = Vec::with_capacity(t.len());

    // Traverse the input and append each character to the output
    for c in t {
        out.push(c);
    }

    // The output now has the same length and content as the input
    out
}

fn main() {
    let input: Vec<char> = vec!['a', 'b', 'c', 'd'];
    let output = solve(input.clone());
    assert_eq!(output, input);
    println!("{:?}", output);
}